	if (_rapierCompareRuntime.resizeObserver) _rapierCompareRuntime.resizeObserver.disconnect();
	_rapierCompareRuntime.resizeObserver = null;
	if (_rapierCompareRuntime.previewCleanup) _rapierCompareRuntime.previewCleanup();
	_rapierCompareRuntime.previewCleanup = null;
	_rapierCompareRuntime.renderThrough = null;
	_rapierCompareRuntime.exact = false;
	c.active = false;
	c.running = false;
	c.lens = 'file';
	c.changeId = null;
	c.currentName = '';
	c.incomingName = '';
	c.currentText = '';
	c.incomingText = '';
	c.result = null;
	c.currentHunk = 0;
	c.snapshot = null;
	c.history = null;
	const state = document.getElementById('compare-state');
	const content = document.getElementById('compare-content');
	const names = document.getElementById('compare-summary-names');
	const counts = document.getElementById('compare-summary-counts');
	if (state) { state.dataset.visible = 'false'; state.replaceChildren(); }
	if (content) content.replaceChildren();
	if (names) names.textContent = '';
	if (counts) counts.textContent = '';
