async function _rapierPortableMarkdownForCopy(canonical, work = null) {
	canonical = (await _rapierDocumentObjects.materialize(canonical, {signal: work?.signal})).source;
	const assets = globalThis.RapierImageAssets;
	if (!assets || !/data:image\/jxl/i.test(canonical)) return canonical;
	try {
		const substitutions = new Map();
		const destinations = (work ? await _rapierRenderModule('render')._rapierDataImageDestinationsAsync(canonical, work)
			: _rapierImageDestinations(canonical, url => !!assets.dataImage(url))).sort((a, b) => b.start - a.start);
		const root = document.createElement('div');
		for (const url of new Set(destinations.map(row => row.destination))) {
			if (assets.dataImage(url)?.codec !== 'image/jxl') continue;
			const image = document.createElement('img');
			image.setAttribute('src', url);
			root.appendChild(image);
		}
		if (!root.childElementCount) return canonical;
		await globalThis.RapierEmbeddedImages.materialize(root, canonical, substitutions, {signal: work?.signal, work, progress: work ? fraction => work.onProgress?.(.4 + .4 * fraction) : null});
		if (!substitutions.size) return canonical;
		let out = canonical;
		for (const row of destinations) {
			const shown = substitutions.get(row.destination);
			if (shown) out = out.slice(0, row.start) + shown + out.slice(row.end);
		}
		return out;
	} catch (error) {
		if (error?.name === 'AbortError' || error?.code === 'cancelled') throw error;
		if (error?.code === 'IMAGE_JXL_UNREADABLE' || error?.code === 'IMAGE_DAMAGED') showToast('The copied Markdown carries its JPEG XL pictures as they are: ' + error.message, 'info');
		return canonical;
	}
}

async function rapierCopy(kind, suppliedCapture = null) {
	let captured = suppliedCapture;
	const requestedDocument = captured ? null : _rapierMutationStamp();
	const task = _rapierProgressTask({label: 'Copying', size: kind === 'formatted' ? (captured ? captured.canonical.length : rapier.document.source.length) : 0,
		current: () => captured ? !captured.stamp || _rapierMutationStampIsCurrent(captured.stamp)
			: _rapierMutationStampSharesDocument(requestedDocument) && requestedDocument.loadToken === Number(rapier.identity.loadToken || 0)});
	const work = task;
	try {
	await task.yield(0);
	if (!captured) captured = await _rapierCaptureSettledExternalDocument({work});
	if (!captured) return false;
	task.check();
	const requested = kind === 'formatted' || kind === 'plain' || kind === 'semantic' ? kind : 'markdown';
	const canonical = captured.canonical;
	const metadata = captured.metadata;

	if (requested === 'markdown' || requested === 'semantic') {

		const portable = metadata.docKind === 'markdown' ? await _rapierPortableMarkdownForCopy(canonical, work) : canonical;
		const dialect = requested === 'semantic' ? 'semantic-markdown' : _rapierPandocDialectEnabled() ? 'pandoc' : null;
		const text = metadata.docKind === 'markdown' && dialect
			? await _rapierExportParse(portable, {kind: dialect, work}) : portable;
		task.check();
		const copied = await _rapierWriteTextClipboard(text, work);
		if (copied === null) return false;
		showToast(copied
			? (metadata.docKind === 'markdown' ? 'copied Markdown' : 'copied source')
			: 'copy failed — try selecting all and copying manually', copied ? 'success' : 'error');
		return copied;
	}

	if (requested === 'plain' && metadata.docKind !== 'markdown') {
		task.check();
		const copied = await _rapierWriteTextClipboard(canonical, work);
		if (copied === null) return false;
		showToast(copied ? 'copied plain text' : 'copy failed — try selecting all and copying manually', copied ? 'success' : 'error');
		return copied;
	}

	const renderer = _rapierRenderModule('render-markdown');
	const payload = await renderer._rapierClipboardPayloadAsync(canonical, metadata, {
		baseName: metadata.filename.replace(/\.[a-z0-9]+$/i, '') || 'document', formatted: requested === 'formatted', work,
		materialize: async root => {
			try { await globalThis.RapierEmbeddedImages.materialize(root, canonical, null, {signal: task.signal, work, progress: fraction => work.onProgress(.6 + .1 * fraction)});
				await _rapierDocumentObjects.materialize(canonical, {root, signal: task.signal, strict: true}); }
			catch (error) { if (error?.name === 'AbortError') throw error; showToast('Image copy failed: ' + error.message, 'error'); return false; }
		},
	});
	if (!payload) return false;
	const {plain, html} = payload;
	await task.yield(.8);

	if (requested === 'plain') {
		task.check();
		const copied = await _rapierWriteTextClipboard(plain, work);
		if (copied === null) return false;
		showToast(copied ? 'copied plain text' : 'copy failed — try selecting all and copying manually', copied ? 'success' : 'error');
		return copied;
	}

	const markdown = metadata.docKind === 'markdown' ? await _rapierPortableMarkdownForCopy(canonical, work) : canonical;
	task.check();
	const formatted = await _rapierWriteClipboardFormats(html, plain, markdown, work);
	if (formatted === null) return false;
	if (formatted) {
		showToast('copied formatted document', 'success');
		return true;
	}

	if (payload.withoutPictures) {
		const lightHtml = await payload.withoutPictures();
		task.check();
		const lightFormatted = await _rapierWriteClipboardFormats(lightHtml, plain, canonical, work);
		if (lightFormatted === null) return false;
		if (lightFormatted) {
			showToast('copied formatted, without pictures', 'info');
			return true;
		}
	}

	task.check();
	const plainFallback = await _rapierWriteTextClipboard(plain, work);
	if (plainFallback === null) return false;
	showToast(plainFallback ? 'copied as plain text' : 'formatted copy failed', plainFallback ? 'info' : 'error');
	return plainFallback;
	} catch (error) {
		if (error?.name !== 'AbortError' && error?.code !== 'cancelled') showToast('Could not copy: ' + String(error?.message || error), 'error');
		return false;
	} finally { task.end(); }
}

const RAPIER_DOCX_MIME = 'application/vnd.openxmlformats-officedocument.wordprocessingml.document';
const RAPIER_DOCX_EMBEDDED_IMAGE_WARN_BYTES = 8 * 1024 * 1024;
const RAPIER_DOCX_IMAGE_MAX_BYTES = 10 * 1024 * 1024;
