function _rapierAnalyzePortability(context, profile) {
	const stats = context && context.stats || {};
	const issues = [];
	if (profile === 'docx') {
		if (stats.docxDiagramSources) issues.push({
			code: 'diagram-source', severity: 'warning', count: stats.docxDiagramSources,
			message: stats.docxDiagramSources + ' diagram' + (stats.docxDiagramSources === 1 ? '' : 's') + ' could not be made into pictures; check the diagram or its plug-in, or continue with the source',
		});
		if (stats.docxUnresolvedLinks) issues.push({
			code: 'internal-links', severity: 'warning', count: stats.docxUnresolvedLinks,
			message: 'some links will stay as text because their destinations could not be found in the Word document; check those links in Rapier',
		});
		if (stats.unresolvedImages) issues.push({
			code: 'linked-images',
			severity: 'warning',
			count: stats.unresolvedImages,
			message: stats.unresolvedImages + ' linked picture' + (stats.unresolvedImages === 1 ? ' will' : 's will') + ' show as a description and link instead',
		});
		if (stats.docxMathSources) issues.push({
			code: 'math-source',
			severity: 'info',
			count: stats.docxMathSources,
			message: stats.docxMathSources + ' equation' + (stats.docxMathSources === 1 ? ' was' : 's were') + ' included as editable TeX source',
		});
		if (stats.svgNodes) issues.push({
			code: 'svg-text',
			severity: 'warning',
			count: stats.svgNodes,
			message: stats.svgNodes + ' inline SVG' + (stats.svgNodes === 1 ? ' will' : 's will') + ' go in as text',
		});
		if (stats.embeddedImageBytes > RAPIER_DOCX_EMBEDDED_IMAGE_WARN_BYTES) issues.push({
			code: 'large-images',
			severity: 'warning',
			count: stats.embeddedImageBytes,
			message: 'pictures total more than 8 MB; this may need a lot of memory',
		});
	}
	return issues;
}

function _rapierDocxReplaceImage(image) {
	const alt = String(image.getAttribute('alt') || '').trim();
	const src = String(image.getAttribute('src') || '').trim();

	if (/^data:image\/(?:png|jpeg|webp|gif|svg\+xml);base64,/i.test(src)) {
		image.removeAttribute('loading');
		image.removeAttribute('decoding');
		image.removeAttribute('crossorigin');
		return;
	}
	const paragraph = document.createElement('p');
	const strong = document.createElement('strong');
	strong.textContent = 'Image: ';
	paragraph.appendChild(strong);
	paragraph.appendChild(document.createTextNode(alt || 'linked image'));
	if (src) {
		paragraph.appendChild(document.createTextNode(' — '));
		const link = document.createElement('a');
		link.href = src;
		link.textContent = src;
		paragraph.appendChild(link);
	}
	image.replaceWith(paragraph);
}

