				const selection = window.getSelection && window.getSelection();
				if (capture.backward && selection?.rangeCount) {
					_rapierInstallSelectionRange(selection, selection.getRangeAt(0).cloneRange(), true);
				}
				const context = _rapierSelectionContext(selection);
				if (context) _rapierRememberToolbarSelection(selection, context.editDiv);
