	if (!units) {
		if (!scope || (rapier.review.seen && rapier.review.seen.restored)) return null;
		for (const owner of rapier.review.moved.values()) {
			if (_rapierScopeOwns(scope, owner.actor, owner.transport)) return null;
		}
		return 0;
	}
