function renderLicenses() {
	const refs = _rapierUi.refs;
	if (!refs) return;
	refs.licensesAppTitle.textContent = 'Rapier v' + _rapierUi.version + ' · copyright 2026 · AGPL-3.0-only';
	const commercialLink = document.getElementById('licenses-commercial');
	// Hosted plugins link to licence information; their directory rules exclude digital checkout links.
	if (commercialLink) commercialLink.href = globalThis.RAPIER_APPS_HOST === true
		? 'https://mcp.rapier.website/licensing.html' : 'https://rapier.website/commercial';
	for (const notice of refs.licensesOverlay.querySelectorAll('.license-text[data-license="rapier-mit"]')) {
		notice.textContent = RAPIER_MIT_NOTICE;
	}
	for (const notice of refs.licensesOverlay.querySelectorAll('.license-text[data-license="pretext"]')) {
		notice.textContent = globalThis.RapierArtifactLayoutDependencies?.license || '';
	}
	renderVisibleSurfaces();
}

// The commercial licence sheet (#commercial-overlay, door rapier.website/commercial, opened only by the boot from that
function _rapierUiOpenPrivacy(door) {
	const name = door === 'commercial' ? 'commercial' : 'privacy';
	closeDialog(_rapierUi.refs.settingsOverlay);
	openDialog(document.getElementById(name + '-overlay'), { panel: '.' + name + '-panel' });
	try { _rapierDoorPathMark(name, true); } catch (_) {}
	_rapierRenderDocumentHead();
}

function _rapierUiClosePrivacy(door) {
	const name = door === 'commercial' ? 'commercial' : 'privacy';
	closeDialog(document.getElementById(name + '-overlay'));
	try { _rapierDoorPathMark(name, false); } catch (_) {}
	_rapierRenderDocumentHead();
}

function _rapierUiOpenLicenses() {
	closeDialog(_rapierUi.refs.settingsOverlay);
	renderLicenses();
	openDialog(_rapierUi.refs.licensesOverlay, { panel: '.licenses-panel' });
}

function _rapierUiCloseLicenses() {
	closeDialog(_rapierUi.refs.licensesOverlay);
	// Opened from the Notes settings panel (which holds About while it is open), the licences close back onto it.
	if (_rapierNotesPart?.settingsBorrowing()) return;
	_rapierUiSetSettingsOpen(true);
}

const _rapierUiNavigator = Object.seal({
	kind: 'outline', sense: 'headings', structural: false, totalLines: 0, collapsed: false,
	clearLine: false, status: '', filter: '', busy: false,
});

function renderCompareChooser() {
	const input = _rapierUi.refs && _rapierUi.refs.compareFileInput;
	if (!input) return;
	input.value = '';
	input.click();
}

function renderNavigatorStatus(message) {
	const refs = _rapierUi.refs;
	if (!refs) return;
	_rapierUiNavigator.status = String(message || '');
	refs.navigatorStatus.textContent = _rapierUiNavigator.status;
}

function renderOutlineReset(model) {
	const refs = _rapierUi.refs;
	if (!refs) return;
	const root = refs.navigatorOutline;
	root.textContent = '';
	root.dataset.outlineNoun = model.noun;
	root.setAttribute('aria-busy', model.busy ? 'true' : 'false');
	_rapierUiNavigator.busy = !!model.busy;
	_rapierUiNavigator.filter = '';
	refs.navigatorFilter.value = '';

	for (const button of document.querySelectorAll('[data-outline-fold-tools]')) {
		button.hidden = !!model.hideFolds;
	}
}

function renderOutlineNote(text, options) {
	const refs = _rapierUi.refs;
	if (!refs) return null;
	const note = document.createElement('p');
	note.className = 'navigator-empty';
	if (options && options.terminal) note.dataset.outlineTerminal = 'true';
	note.textContent = String(text || '');
	refs.navigatorOutline.appendChild(note);
	return note;
}

function renderOutlineList(model) {
	const refs = _rapierUi.refs;
	if (!refs) return;
	if (model.clear) refs.navigatorOutline.textContent = '';
	if (model.busy != null) {
		refs.navigatorOutline.setAttribute('aria-busy', model.busy ? 'true' : 'false');
		_rapierUiNavigator.busy = !!model.busy;
	}
}

function renderOutlineButton(item, current, onActivate) {
	const refs = _rapierUi.refs;
	if (!refs) return;
	const button = document.createElement('button');
	button.type = 'button';
	button.className = 'navigator-outline__item';
	button.style.setProperty('--outline-level', String(item.level || 1));
	button.textContent = item.label || 'untitled heading';
	button.dataset.outlineText = button.textContent;
	button.dataset.current = current ? 'true' : 'false';
	if (current) button.setAttribute('aria-current', 'location');
	button.addEventListener('click', () => onActivate(button));
	refs.navigatorOutline.appendChild(button);
}

function renderOutlineFilter(value) {
	const refs = _rapierUi.refs;
	if (!refs) return 0;
	const root = refs.navigatorOutline;
	_rapierUiNavigator.filter = String(value || '');
	const terms = String(value || '').trim().toLocaleLowerCase().split(/\s+/).filter(Boolean);
	const buttons = Array.from(root.querySelectorAll('.navigator-outline__item'));
	let visible = 0;
	buttons.forEach(button => {
		const haystack = String(button.dataset.outlineText || button.textContent || '').toLocaleLowerCase();
		const match = terms.every(term => haystack.includes(term));
		button.hidden = !match;
		if (match) visible++;
	});
	let empty = root.querySelector('[data-outline-filter-empty]');
	const terminal = root.querySelector('[data-outline-terminal]');
	const noun = String(root.dataset.outlineNoun || 'headings');
	if (root.getAttribute('aria-busy') === 'true') {
		empty?.remove();
		renderNavigatorStatus('reading structure');
		return visible;
	}
	if (!visible && terms.length && !terminal) {
		if (!empty) {
			empty = document.createElement('p');
			empty.className = 'navigator-empty';
			empty.dataset.outlineFilterEmpty = 'true';
			empty.textContent = 'no matching ' + noun;
			root.appendChild(empty);
		}
	} else empty?.remove();
	if (terminal) {
		renderNavigatorStatus(terminal.textContent || '');
	} else if (terms.length) {
		renderNavigatorStatus(visible
			? String(visible) + ' matching ' + (visible === 1
				? (noun === 'declarations' ? 'declaration' : 'heading') : noun)
			: 'no matching ' + noun);
	} else if (buttons.length) {
		renderNavigatorStatus(String(buttons.length) + ' ' + (buttons.length === 1
			? (noun === 'declarations' ? 'declaration' : 'heading') : noun));
	}
	return visible;
}

function renderNavigator() {
	const refs = _rapierUi.refs;
	if (!refs) return;
	const state = _rapierUiNavigator;
	const outline = state.kind === 'outline';
	refs.navigatorTitle.textContent = document.body.classList.contains('rapier-draw-open') ? 'comments and agent'
		: state.structural ? 'declarations' : (outline ? state.sense : 'go to line');
	refs.navigatorTools.hidden = !outline;
	refs.navigatorOutline.hidden = !outline;
	refs.navigatorFilter.setAttribute('placeholder', 'filter ' + state.sense);
	refs.navigatorFilter.setAttribute('aria-label', 'filter ' + state.sense);
	refs.navigatorFold.setAttribute('aria-label',
		state.collapsed ? 'expand all sections' : 'collapse all sections');
	refs.navigatorFold.setAttribute('aria-pressed', state.collapsed ? 'true' : 'false');
	refs.navigatorFold.textContent = state.collapsed ? 'EXPAND' : 'COLLAPSE';
	const lineForm = state.kind === 'line' || state.structural;
	refs.gotoForm.hidden = !lineForm;
	refs.gotoForm.dataset.composite = state.structural ? 'true' : 'false';
	refs.gotoInput.max = String(state.totalLines || 1);
	if (state.clearLine) { state.clearLine = false; refs.gotoInput.value = ''; }
	refs.navigatorExpand.hidden = !state.structural;
	refs.gotoRange.hidden = !lineForm;
	refs.gotoRange.textContent = '1 – ' + (state.totalLines || 1);
}

function _rapierUiCircleGrowth(panel, opening, circle_) {
	if (!panel || typeof panel.animate !== 'function') return false;
	if (window.matchMedia?.('(prefers-reduced-motion: reduce)').matches) return false;
	const fab = circle_ || _rapierUi.refs.scrollFab;
	if (!fab) return false;
	if (opening ? (!circle_ && !fab.classList.contains('visible')) : panel.dataset.grewFromCircle !== '1') return false;
	const circle = fab.getBoundingClientRect();
	const box = panel.getBoundingClientRect();
	if (!box.width || !box.height) return false;
	const x = circle.left + circle.width / 2 - box.left;
	const y = circle.top + circle.height / 2 - box.top;

	const seed = Math.max(0.05, Math.min(circle.width / box.width, circle.height / box.height));
	const restingOrigin = panel.style.transformOrigin;
	panel.style.transformOrigin = x.toFixed(1) + 'px ' + y.toFixed(1) + 'px';
	const small = { transform: 'scale(' + seed.toFixed(3) + ')', opacity: '0' };
	const whole = { transform: 'scale(1)', opacity: '1' };
	const travel = panel.animate(opening ? [small, whole] : [whole, small],
		{ duration: opening ? 220 : 160, easing: opening ? 'ease-out' : 'ease-in', fill: 'none' });
	const settle = () => { panel.style.transformOrigin = restingOrigin; };
	travel.finished.then(settle, settle);
	if (opening) panel.dataset.grewFromCircle = '1';
	else delete panel.dataset.grewFromCircle;
	return true;
}

function _rapierUiOpenNavigator(detail) {
	const refs = _rapierUi.refs;
	const state = _rapierUiNavigator;
	state.kind = detail.kind;
	state.structural = detail.structural === true;
	state.sense = detail.sense || 'headings';
	state.collapsed = false;
	state.totalLines = detail.totalLines || 0;

	state.clearLine = true;
	renderNavigator();
	openDialog(refs.navigatorOverlay, { panel: '.navigator-panel', noreturn: true, noautofocus: true });
	_rapierUiCircleGrowth(refs.navigatorOverlay.querySelector('.navigator-panel'), true);
	if (document.body.classList.contains('rapier-draw-open')) refs.navigatorClose.focus({ preventScroll: true });
	else if (state.kind === 'line') refs.gotoInput.focus({ preventScroll: true });
	else if (state.structural) refs.navigatorTitle.focus({ preventScroll: true });
	else refs.navigatorClose.focus({ preventScroll: true });
}

const _rapierUiPlatform = { windowsBusy: false, recents: [] };

function _rapierUiOpenPlatformPayload(payload) {
	return payload ? rapierOpenPlatformPayload(payload) : false;
}

async function _rapierUiBeginOpenDocument(event) {
	const refs = _rapierUi.refs;
	closeDialog(refs.settingsOverlay);
	if (_rapierEmbed.active) return _rapierEmbed.fileOpen.begin(event);
	const app = globalThis.RAPIER_APPS_HOST === true && globalThis.RapierMcpApp;
	if (event?.isTrusted && app?.status?.canImport) { void app.importFile(event); return; }
	const platform = window.RapierPlatform;
	if (platform && typeof platform.files.open === 'function') {
		Promise.resolve(platform.files.open()).then(_rapierUiOpenPlatformPayload).catch(error => {
			try { console.warn('[rapier] platform open failed', error); } catch (_) {}
			showToast('could not open that file', 'error');
		});
		return;
	}
	await _rapierPrepareFileChooser('open');
	refs.fileInput.click();
}

function _rapierUiBeginUploadDocument() {
	closeDialog(_rapierUi.refs.settingsOverlay);
	const platform = window.RapierPlatform;
	if (!platform || !platform.files.upload) return;
	Promise.resolve(platform.files.upload()).then(_rapierUiOpenPlatformPayload).catch(error => {
		try { console.warn('[rapier] local upload failed', error); } catch (_) {}
		showToast('could not upload that file', 'error');
	});
}

async function _rapierUiInstallWindows() {
	const platform = window.RapierPlatform;
	if (!platform || !platform.installation.install) return;
	const updating = _rapierUiPlatformFacts().windowsUpdate;
	_rapierUiPlatform.windowsBusy = true;
	renderSettings();
	try {
		await platform.installation.install();
		showToast(updating ? 'Rapier updated' : 'Rapier installed', 'success');
	} catch (_) {
		showToast(updating ? 'Rapier update failed' : 'Rapier installation failed', 'error');
	} finally {
		_rapierUiPlatform.windowsBusy = false;
		renderSettings();
	}
}

async function _rapierUiUninstallWindows() {
	const platform = window.RapierPlatform;
	if (!platform || !platform.installation.uninstall) return;
	const transitionGuard = await _rapierConfirmDirtyTransition({
		title: 'uninstall Rapier',
		message: 'Save changes before uninstalling Rapier?',
		discardLabel: 'uninstall without saving',
	});
	if (!transitionGuard || !_rapierMutationStampIsCurrent(transitionGuard)) return;
	_rapierUiPlatform.windowsBusy = true;
	renderSettings();
	try { await platform.installation.uninstall(); }
	catch (_) { showToast('Rapier uninstall failed', 'error'); }
	finally {
		_rapierUiPlatform.windowsBusy = false;
		renderSettings();
	}
}

async function _rapierUiOpenWelcome() {
	closeDialog(_rapierUi.refs.settingsOverlay);
	if (_rapierNotesPart?.settingsBorrowing()) {
		_rapierNotesPart.settingsOpen(false);
		if (await _rapierNotesPart.editor() !== true) return;
	}
	if (await rapierOpenWelcomeDocument() === false) return;
	_rapierUiApplyReadOnly();
}

function _rapierUiOpenIconColour() {
	if (!_rapierRequireFeature('icon', { source: 'icon' })) return;
	const overlay = _rapierUi.refs.iconOverlay, sheet = overlay.querySelector('.info-action-sheet');
	openDialog(overlay, {panel: '.info-action-sheet', noautofocus: true});
	renderSwitch(_rapierUi.refs.iconSwatches, _rapierUiPro.launcherIcon);
	sheet.focus({preventScroll: true});
}

function _rapierUiOpenInterchange(overlay) {
	if (overlay === _rapierUi.refs.shareOverlay && !_rapierEmbedFeatureAllowed('share')) return false;
	const refs = _rapierUi.refs;
	if (overlay === refs.shareOverlay) _rapierShareLedgerReset();
	_rapierRenderPageReturn();
	closeDialog(refs.exportOverlay);
	closeDialog(refs.copyOverlay);
	closeDialog(refs.shareOverlay);
	openDialog(overlay, { panel: '.settings-panel' });
}

